static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    if (dayOfMonth <= dayStep) {
        dayOfMonth = 1;
    } else if ((dayOfMonth - dayStep) % 7 == 0) {
        dayOfMonth -= dayStep;
    } else {
        dayOfMonth -= dayStep + 7 - ((dayOfMonth - dayStep) % 7);
    }

    return (long) year * 10000 + month * 100 + dayOfMonth;
}

