        if (ch == '$' && i + 1 < len) {
            char next = value.charAt(i + 1);
            if (next == '{') {
                int j = value.indexOf('}', i);
                if (j != -1) {
                    String varName = value.substring(i + 2, j);
                    String varValue = props.getProperty(varName);
                    if (varValue != null) {
                        buffer.append(varValue);
                    } else {
                        buffer.append("${").append(varName).append("}");
                    }
                    i = j + 1;
                    continue;
                }
            } else if (Character.isLetterOrDigit(next) || next == '_') {
                StringBuilder varName = new StringBuilder();
                varName.append(next);
                i++;
                while (i < len) {
                    ch = value.charAt(i);
                    if (Character.isLetterOrDigit(ch) || ch == '_') {
                        varName.append(ch);
                        i++;
                    } else {
                        break;
                    }
                }
                String varValue = props.getProperty(varName.toString());
                if (varValue != null) {
                    buffer.append(varValue);
                } else {
                    buffer.append("${").append(varName).append("}");
                }
                continue;
            }
        }
