            if (desiredCapacity % 100 <= 10) {
                desiredCapacity += 10 - (desiredCapacity % 10);
            } else if (desiredCapacity % 50 <= 5) {
                desiredCapacity += 5 - (desiredCapacity % 5);
            } else if (desiredCapacity % 10 <= 4) {
                desiredCapacity += 4 - (desiredCapacity % 10);
            } else {
                desiredCapacity++;
            }
        }
    }
    return desiredCapacity;
}

